  function drawVoice(){setPage('voice','<article class="sw-card"><form class="sw-form" data-sw-form="voice" data-sw-voice><div class="sw-actions">'+button('🎙 Record','mic','aria-label="Start voice recording"')+'<span data-sw-mic-state>Review your text before sending</span></div>'+area('Message','message','','required maxlength="5000" placeholder="Speak or type a message or cross-app action"')+'<div class="sw-form two"><label>Destination<select name="destination"><option value="ai">AI Bot · remembered conversation</option><option value="private">Private · do not remember</option><option value="twitch">Twitch chat</option><option value="discord">Discord channel</option></select></label><label data-sw-connection-wrap hidden>Connected channel<select name="connectionId"></select></label></div><button class="button primary">Send</button></form><p>'+(control.operationMode==='read-only'?'Provider replies are captured in Simulation Rooms. External AI requests are disabled in this test environment.':'Provider messages go to the selected connected channel.')+'</p>'+button('Open Simulation Rooms','rooms')+'</article><article class="sw-card"><div class="sw-actions"><h3>Conversation & delivery history</h3>'+button('Refresh history','history')+button('Clear history','clear-history')+'</div><div class="sw-history" data-sw-history></div></article>');void drawHistory()}
  async function drawHistory(){try{const {history}=await api('/voice/history'),node=slots('voice')?.querySelector('[data-sw-history]');if(node)node.innerHTML=[...memoryHistory,...history].map(h=>'<article><strong>'+esc(h.destination)+'</strong><p>'+esc(h.message)+'</p><p>'+esc(h.output||h.reason||h.state||h.status||'Queued')+'</p></article>').join('')||'<p>No messages sent yet.</p>';for(const h of history)if(h.jobId&&!['succeeded','failed','dead-letter','cancelled'].includes(h.state))pollJob(h.jobId)}catch(e){status(e.message,true)}}
  async function pollJob(id){if(pendingJobs.has(id))return;pendingJobs.add(id);try{for(let n=0;n<80;n++){const result=await api('/voice/jobs/'+encodeURIComponent(id)),job=result.job??result;if(['succeeded','failed','dead-letter','cancelled'].includes(job.state)){const text=job.result?.text||job.result?.output?.text||(job.state==='succeeded'?'Request completed.':'Request did not complete.');const privateEntry=memoryHistory.find(h=>h.jobId===id);if(privateEntry){privateEntry.output=text;privateEntry.state=job.state}status(text,job.state!=='succeeded');if(job.state==='succeeded')window.dispatchEvent(new CustomEvent('spmt:assistant-reply',{detail:{id:job.id||id,text}}));await drawHistory();return}await new Promise(resolve=>setTimeout(resolve,1000))}status('Still running. Refresh history to check the result.')}catch(e){status(e.message,true)}finally{pendingJobs.delete(id)}}
  let ledgerBefore=null;
  async function drawLedger(older=false){const node=slots('economy')?.querySelector('[data-sw-ledger]');if(!node)return;try{const result=await api('/economy/ledger'+(older&&ledgerBefore?'?before='+ledgerBefore:''));ledgerBefore=result.nextBefore;node.innerHTML=result.entries.map(row=>'<article class="sw-card"><strong>'+esc(row.userId)+' · '+esc(row.delta>0?'+'+row.delta:row.delta)+'</strong><p>'+esc(row.before)+' → '+esc(row.after)+' · '+esc(row.reason)+'</p><small>'+esc(row.actorId||'Currency runtime')+' · '+esc(new Date(row.occurredAt).toLocaleString())+'</small></article>').join('')||'<p>No balance changes recorded yet.</p>';slots('economy').querySelector('[data-sw-action="ledger-older"]').disabled=!ledgerBefore;}catch(e){node.textContent=e.message;}}
  function drawOverlays(){setPage('overlays','<article class="sw-card"><h3>Public and Personal stream outputs</h3><p>Use the shared Overlay Bay to add, arrange and preview widgets. Your Public output is the browser source for OBS; Personal follows your signed-in workspace.</p><div class="sw-actions">'+button('Open Overlay Bay','overlay-bay')+button('Copy Public URL','copy-public')+button('Copy Personal URL','copy-personal')+button('Open Simulation Rooms','rooms')+'</div></article><article class="sw-card"><h3>Registered widgets</h3>'+((platform.overlayWidgets||[]).map(w=>'<p>'+esc(w.manifest?.title||w.name||w.widgetId||w.id)+' · '+esc(w.manifest?.appId||w.ownerAppId||w.appId||'')+'</p>').join('')||'<p>No widgets registered for this tenant.</p>')+'</article><article class="sw-card"><h3>Test commands alongside your stream</h3><p>Create a room in Workspace, then pin it to one of the three embed slots. The room stays open when you switch apps.</p></article>')}
  function drawDevices(){if(!owner()){setPage('devices','<p>The tenant owner can authorize their paired devices.</p>');return}setPage('devices','<article class="sw-card"><p>Select the actions StreamWeaver may run on each paired device. Only your enabled flows can request those actions. Revoking access prevents pending jobs from starting.</p><div class="sw-actions">'+button('Pair a device in Companion','companion')+button('Refresh devices','refresh')+'</div></article>'+'<form class="sw-card sw-form" data-sw-form="pair-device"><h3>Pair this computer</h3>'+field('Computer name','name','','text','required maxlength="100"')+'<button class="button" type="submit">Create pairing code</button><code data-device-pairing></code><p data-device-pairing-expiry></p><small>On the computer running OBS, build ApolloStation and run npm run companion:obs with this one-time code. OBS WebSocket must be enabled; its password stays in the local OBS_PASSWORD environment variable.</small></form>'+(control.deviceError?'<p>'+esc(control.deviceError)+'</p>':'')+(control.devices||[]).map(device=>{const grant=device.automationGrants?.find(g=>g.appId==='streamweaver'),choices=[['obs.scene.set','Change OBS scene','obs.scene'],['obs.source.visibility.set','Show or hide OBS sources','obs.scene'],['media.play','Play media','media.playback'],['media.pause','Pause media','media.playback'],['media.seek','Seek media','media.playback'],['media.volume.set','Set media volume','media.playback'],['media.mute.set','Mute media','media.playback']].filter(c=>device.capabilities.includes(c[2]));return '<form class="sw-card sw-form" data-sw-form="devices" data-device-id="'+esc(device.deviceId)+'"><h3>'+esc(device.name)+'</h3>'+choices.map(([action,label])=>'<label class="sw-check"><input name="device-action" type="checkbox" value="'+action+'"'+(grant?.actions.includes(action)?' checked':'')+'>'+label+'</label>').join('')+'<button class="button" type="submit">Save device access</button><small>Clear every action and save to revoke StreamWeaver access.</small></form>'}).join('')+(!(control.devices||[]).length?'<p>Pair your computer through Companion to add OBS and local media controls.</p>':''))}
  async function drawActivity(){if(!owner()){setPage('activity','<p>The tenant owner can review command activity.</p>');return}try{const {runs}=await api('/activity');setPage('activity','<div class="sw-actions">'+button('Refresh runs','activity')+'<a class="button" href="'+root+'/diagnostics">Download diagnostics</a>'+button('Open Simulation Rooms','rooms')+'</div>'+(runs.map(r=>'<article class="sw-card"><div class="sw-actions"><strong>'+esc(r.command)+'</strong><span class="sw-badge">'+esc(r.state)+'</span></div><p>'+esc(r.actor+' · '+r.provider+' · '+r.occurredAt)+'</p><p>'+esc(r.input)+'</p>'+(r.error?'<p>'+esc(r.error)+'</p>':'')+'<ol>'+(r.steps||[]).map(s=>'<li>'+esc(s.type+' · '+s.state)+(s.output?'<p>'+esc(s.output)+'</p>':'')+'</li>').join('')+'</ol></article>').join('')||'<article class="sw-card"><p>No commands have run in connected chat yet. Simulation Room history stays with its room.</p></article>'))}catch(e){status(e.message,true)}}
  async function refresh(){if(loading)return;loading=true;try{const [c,f]=await Promise.all([api(),api('/flows')]);control=c;library=f;drawSetup();drawCommunity();drawCommands();drawDevices();if(!editor)drawBuilder();if(!initialized){drawVoice();drawPersona();drawEconomy();drawIntegrations();drawOverlays();void drawActivity();initialized=true}status('StreamWeaver is up to date.')}catch(e){status(e.message,true);if(!initialized)for(const id of ['setup','community','builder','voice','commands','persona','integrations','economy','overlays','activity'])setPage(id,'<article class="sw-card"><p>'+esc(e.message)+'</p>'+button('Retry','refresh')+'</article>')}finally{loading=false}}
  function changeEditor(target){if(!editor)return;const ci=Number(target.closest('[data-command-index]')?.dataset.commandIndex),command=editor.commands[ci],stepId=target.closest('[data-step-id]')?.dataset.stepId,action=editor.actions.find(a=>a.id===stepId);if(target.dataset.editor)editor[target.dataset.editor]=target.value;if(target.dataset.commandField&&command){const key=target.dataset.commandField;command[key]=key==='aliases'?target.value.split(',').map(v=>v.trim()).filter(Boolean):['cooldownSeconds','globalCooldownSeconds'].includes(key)?Number(target.value):['caseSensitive','enabled'].includes(key)?target.value==='true':target.value;if(key==='minimumRole')delete command.migrationNote}if(target.hasAttribute('data-step-enabled')&&action)action.enabled=target.checked;if(target.dataset.edgeOutcome&&action){const outcome=target.dataset.edgeOutcome;command.edges=command.edges.filter(e=>e.source!==action.id||e.outcome!==outcome);for(const option of Array.from(target.options).filter(o=>o.selected))command.edges.push({source:action.id,target:option.value,outcome});}if(target.hasAttribute('data-step-type')&&action){action.type=target.value;action.config=action.type==='condition'?{operator:'==',left:'{{lastOutput}}',right:''}:action.type==='ai-response'?{input:'%args%',saveAs:'aiResponse'}:action.type==='run-native'?{capability:'streamweaver.donor-command.v1',donorId:library.community[0].commands[0].donorId}:action.type==='run-action'?{action:control.botActions[0]?.id,args:{}}:action.type==='obs-scene'?{deviceId:'',sceneName:''}:action.type==='obs-source'?{deviceId:'',sceneName:'',sourceName:'',visible:true}:action.type==='device-command'?{deviceId:'',action:'media.pause',payload:{}}:{};drawBuilder()}if(target.dataset.devicePayload&&action){action.config.payload=action.config.payload||{};action.config.payload[target.dataset.devicePayload]=target.dataset.devicePayload==='muted'?target.value==='true':target.type==='number'?Number(target.value)*Number(target.dataset.scale||1):target.value;}if(target.dataset.config&&action){const key=target.dataset.config;if(key==='saveAs'&&!target.value){delete action.config.saveAs;return;}action.config[key]=key==='visible'?target.value==='true':['milliseconds','expiresSeconds'].includes(key)?Number(target.value):['args','payload','options','relations'].includes(key)?JSON.parse(target.value||'{}'):target.value;if(key==='action'&&action.type==='device-command'){action.config.payload={inputName:action.config.payload?.inputName||'',...(target.value==='media.volume.set'?{volume:0.85}:target.value==='media.seek'?{positionMs:0}:target.value==='media.mute.set'?{muted:true}:{})};drawBuilder();}}}
