    if(action==='copy'){const value=await api('/flows/copy',{packageId:id});await refresh();editor=value.package;revision=editor.updatedAt;drawBuilder();navigate('builder');return}
    if(action==='inspect'){const p=getPackage(id);const dialog=document.createElement('dialog');dialog.className='sw-dialog';dialog.innerHTML='<h3>'+esc(p.name)+'</h3>'+p.commands.map(c=>'<h4>'+esc(c.trigger)+'</h4><ol>'+c.actionIds.map(id=>{const a=p.actions.find(s=>s.id===id);return '<li>'+esc(a.type)+'<pre>'+esc(JSON.stringify(a.config,null,2))+'</pre></li>'}).join('')+'</ol>').join('')+button('Close','dialog-close');document.body.append(dialog);dialog.addEventListener('close',()=>dialog.remove());dialog.showModal();return}
    if(action==='dialog-close'){b.closest('dialog').close();return}
    if(action==='preview'){const p=getPackage(id),value=await api('/flows/preview',{packageId:id,commandId:p.commands.find(c=>c.role==='primary')?.id});window.dispatchEvent(new CustomEvent('spmt:open-simulation-rooms',{detail:{roomId:value.roomId}}));return}
