    if(['uninstall','publish','delete'].includes(action)){if(action==='delete'&&!confirm('Delete this private draft and remove its installation?'))return;await api('/flows/'+action,{packageId:id});await refresh();return}
    if(action==='graph-on'||action==='graph-off'){const c=editor.commands[ci];if(action==='graph-on')c.edges=c.actionIds.slice(0,-1).map((source,i)=>({source,target:c.actionIds[i+1],outcome:editor.actions.find(a=>a.id===source).type==='condition'?'true':'success'}));else delete c.edges;drawBuilder();return}
    if(action==='command-add'){const c=makeCommand();editor.commands.push(c);addStep(c);drawBuilder();return}
    if(action.startsWith('step-')||action==='command-remove'){const c=editor.commands[ci],si=Number(b.dataset.stepIndex);if(action==='step-add')addStep(c);if(action==='step-remove')c.actionIds.splice(si,1);if(action==='step-up'&&si>0)[c.actionIds[si-1],c.actionIds[si]]=[c.actionIds[si],c.actionIds[si-1]];if(action==='step-down'&&si<c.actionIds.length-1)[c.actionIds[si+1],c.actionIds[si]]=[c.actionIds[si],c.actionIds[si+1]];if(action==='command-remove')editor.commands.splice(ci,1);const used=new Set(editor.commands.flatMap(x=>x.actionIds));editor.actions=editor.actions.filter(a=>used.has(a.id));for(const command of editor.commands)if(command.edges)command.edges=command.edges.filter(e=>command.actionIds.includes(e.source)&&command.actionIds.includes(e.target));drawBuilder();return}
